import { Container, Sprite, Text } from '../../../core/fff.js';
import { BT } from '../../../engine/BT.js';
import { Config } from '../../../engine/Config.js';
import { Datas } from '../../../engine/Datas.js';

export class HudPanel extends Container {
    constructor(pX, pY, pSize = 1) {
        super();

        this.eventMode = 'none';

        this.x = pX;
        this.y = pY;

        let ul = new Sprite(Datas.atlas[Datas.BOX_UL]);
        this.addChild(ul);

        for (let i = 1; i < pSize; i++) {
            let u = new Sprite(Datas.atlas[Datas.BOX_U]);
            u.x = i * 16;
            this.addChild(u);
        }

        let ur = new Sprite(Datas.atlas[Datas.BOX_UR]);
        ur.x = 16 * pSize;
        this.addChild(ur);


        let dl = new Sprite(Datas.atlas[Datas.BOX_DL]);
        dl.y = 16;
        this.addChild(dl);

        for (let i = 1; i < pSize; i++) {
            let d = new Sprite(Datas.atlas[Datas.BOX_D]);
            d.x = i * 16;
            d.y = 16;
            this.addChild(d);
        }

        let dr = new Sprite(Datas.atlas[Datas.BOX_DR]);
        dr.position.set(16 * pSize, 16);
        this.addChild(dr);

        // Textfield
        this.scoreText = new Text(BT.pad0(Datas.score.toString(), 4), { fontFamily: Config.DEFAULT_FONT, fill: 0x0, fontSize: 7, letterSpacing: 3 });
        this.scoreText.position.set(5, 12);
        this.addChild(this.scoreText);
    }

    update(){
        this.scoreText.text = BT.pad0(Datas.score.toString(), 4);
    }
}