import { gsap } from 'gsap';
import { Container, Sprite } from '../../../core/fff.js';
import { Animator } from '../../../engine/Animator.js';
import { ControlableContainer } from '../../../engine/ControlableContainer.js';
import { Datas } from '../../../engine/Datas.js';
import { GameInput } from '../../../engine/GameInput.js';
import { PlatformerBody } from '../../../engine/PlatformerBody.js';
import { SATCircle } from '../../../utils/SAT.js';

/**
 * Le heros du platformer : un Container (et non un Sprite) car il est compose de plusieurs sprites
 * (idle, course animee, saut, coeurs de vie).
 *
 * Toute la physique vit dans PlatformerBody (moteur) : ici on ne fait que
 *  - traduire les touches en intentions (direction, saut) ;
 *  - afficher l'etat du corps (quel sprite, de quel cote, la tete en bas au plafond).
 */
export class PlatformPlayer extends ControlableContainer {
    /**
     * @param pGrid TileGrid des collisions ; null pour un simple "porteur d'input" (ecrans titre/game over)
     */
    constructor(pGameInput, pInitialX = 0, pInitialY = 0, pScreenRef = null, pGrid = null) {
        super(pGameInput);

        this.x = pInitialX;
        this.y = pInitialY;
        this.screenRef = pScreenRef;

        // corps physique (boite 20x30 px : un peu plus etroite que le sprite de 32 px, comme dans la
        // plupart des platformers, pour pardonner les frottements dans les coins)
        this.body = null;
        if (pGrid) {
            this.body = new PlatformerBody(pGrid);
            this.body.reset(pInitialX, pInitialY);
        }
        this.onBodyEvent = null; // (nom) => void : 'jump', 'doubleJump', 'wallJump', 'land', 'hang', 'release'

        // zone de ramassage (pieces, porte) : cercle SAT comme avant, centre sur le joueur
        this.bb = new SATCircle();
        this.bb.radius = 12;
        this.bb.x = this.x;
        this.bb.y = this.y;

        // un seul sprite anime : idle / run (4 images) / jump
        const fRun = [Datas.RUN0, Datas.RUN1, Datas.RUN2, Datas.RUN3].map((k) => Datas.atlas[k]);
        this.anim = new Animator({
            idle: { frames: [Datas.atlas[Datas.IDLE]] },
            run: { frames: fRun, fps: 9 },
            jump: { frames: [Datas.atlas[Datas.JUMP]] }
        }, 'idle');
        this.anim.anchor.set(.5);
        this.addChild(this.anim);

        this.heartContainer = new Container();
        this.heartContainer.position.set(-12, -20);
        this.addChild(this.heartContainer);

        for (let i = 0; i < 3; i++) {
            const heart = new Sprite(Datas.atlas[Datas.lives > i ? Datas.HEART : Datas.HEART2]);
            heart.scale.set(.5, .5);
            heart.position.set(i * 8, 0);
            this.heartContainer.addChild(heart);
        }

        this.heartContainer.alpha = 1;
        this.heartContainer.visible = true;
        gsap.to(this.heartContainer, {
            alpha: 0, duration: 1.5, delay: 1.5, ease: "power1.out", onComplete: () => {
                this.heartContainer.visible = false;
            }
        });

        this.frameCount = 0;
        this.hurtDurationTime = 5;
        this.hurtDuration = 0;
        this.faceLeft = false;
    }

    // ---- etat expose a l'ecran ----
    get grounded() { return !!this.body && this.body.onGround; }
    get hanging() { return !!this.body && this.body.hanging; }

    // ---- input : les ecrans (titre, game over) utilisent les evenements "appui" ----
    // Un OnPress n'est appele qu'UNE fois par appui (front montant) : plus besoin de drapeau
    // "insertCoin" pour eviter les repetitions comme avec les anciens xxxIsDown().
    action1OnPress() { if (this.screenRef) this.screenRef.playerAction(GameInput.ACTION1); }
    action2OnPress() { if (this.screenRef) this.screenRef.playerAction(GameInput.ACTION2); }
    action3OnPress() { if (this.screenRef) this.screenRef.playerAction(GameInput.ACTION3); }

    hurt() {
        this.hurtDuration = this.hurtDurationTime;
    }

    /** un pas de physique (dt fixe) : lit les touches, fait avancer le corps */
    step(dt) {
        const gi = this.gameInput;
        const move = (gi.right.isDown ? 1 : 0) - (gi.left.isDown ? 1 : 0);
        const b = this.body;

        b.step(dt, { move, down: gi.down.isDown, jumpKey: gi.action1 });

        if (move !== 0) this.faceLeft = move < 0;

        // le monde boucle horizontalement / verticalement
        const W = this.body.grid.cols * this.body.grid.tileSize;
        if (b.x < -16) b.x += W;
        if (b.x > W - 16) b.x -= W;
        if (b.y > this.body.grid.rows * this.body.grid.tileSize + 32) { b.y = -32; }
        if (b.y < -128) { b.y = -128; b.vy = Math.max(b.vy, 0); }

        if (this.onBodyEvent) b.events.forEach((e) => this.onBodyEvent(e));
    }

    /** synchronise l'affichage avec le corps (a chaque frame, pas a chaque pas fixe) */
    updateView(pDt = 0) {
        const b = this.body;
        this.x = b.x;
        this.y = b.y;
        this.bb.x = b.x;
        this.bb.y = b.y;

        const sx = this.faceLeft ? -1 : 1;
        const sy = b.hanging ? -1 : 1; // accroche : la tete en bas

        // clip joue selon l'etat du corps
        let clip;
        if (b.hanging) clip = Math.abs(b.vx) > 5 ? 'run' : 'idle';
        else if (b.onGround) clip = Math.abs(b.vx) > 12 ? 'run' : 'idle';
        else clip = 'jump';
        this.anim.play(clip);
        this.anim.update(pDt);

        // Centrage du VISUEL dans le cercle de collision : les sprites 16x16 ne sont pas centres dans
        // leur cadre (pixels opaques mesures : idle/course y 3..16, saut y 1..14 -> centre du dessin
        // decale de +1.5 / +1 / -0.5 px par rapport au centre du cadre). On compense ; retourne la tete
        // en bas (accroche), le decalage s'inverse.
        const flip = b.hanging ? -1 : 1;
        if (clip === 'jump') {
            // contre un mur : le heros regarde le mur
            this.anim.scale.set(b.sliding ? b.wallDir : sx, 1);
            this.anim.y = .5;
        } else {
            this.anim.scale.set(sx, sy);
            this.anim.y = (clip === 'run' ? -1 : -1.5) * flip;
        }

        if (this.hurtDuration > 0) {
            const flash = this.frameCount % 5 !== 0;
            const tint = flash ? 0xCC0000 : 0xFFFFFF;
            this.anim.tint = tint;
            if (!flash) this.hurtDuration--;
        }
        this.frameCount++;
    }
}
