/**
 * Collisions AABB (rectangle) contre une grille de tuiles pleines/vides.
 * Pur calcul, aucune dependance a Pixi : testable et reutilisable dans n'importe quel platformer
 * ou jeu a base de tuiles.
 *
 * Principe : on deplace la boite AXE PAR AXE (d'abord X, puis Y) et on la recolle contre le bord
 * de la tuile touchee. C'est ce qui donne des contacts propres :
 *   - on sait de quel cote on a touche (sol, plafond, mur gauche/droit) ;
 *   - on glisse le long d'un mur au lieu de s'y coller ;
 *   - pas de "demi-separation" ni de boite fantome plus grosse que le sprite.
 * Une tuile pleine n'occupe pas forcement toute sa case : voir l'option `shapes` de TileGrid (ex : un
 * sol dont seule la moitie haute est opaque). Les deplacements sont decoupes en petits morceaux (< demi-tuile) pour ne jamais traverser une
 * tuile, meme apres une grosse frame.
 */

const EPS = 1e-4;

export class TileGrid {
    /**
     * @param pCols      nombre de colonnes
     * @param pRows      nombre de lignes
     * @param pTileSize  taille d'une tuile en pixels
     * @param pData      tableau plat (ligne par ligne) : > 0 = tuile pleine (valeur = id de tuile)
     * @param pOriginX   coordonnee monde du coin haut-gauche de la tuile (0,0)
     * @param pOriginY   idem en y
     * @param pShapes    optionnel : { [idTuile]: { x0, y0, x1, y1 } } rectangle de collision en pixels,
     *                   relatif au coin haut-gauche de la case. Par defaut : toute la case.
     *                   Ex : { 1: { x0: 0, y0: 0, x1: 32, y1: 12 } } = tuile dont seuls les 12 px du haut sont solides
     */
    constructor(pCols, pRows, pTileSize, pData, pOriginX = 0, pOriginY = 0, pShapes = {}) {
        this.cols = pCols;
        this.rows = pRows;
        this.tileSize = pTileSize;
        this.data = pData;
        this.originX = pOriginX;
        this.originY = pOriginY;
        this.shapes = pShapes;
    }

    /** vrai si la tuile (col,row) est pleine ; hors grille = vide (le joueur peut sortir/boucler) */
    solidAt(pCol, pRow) {
        if (pCol < 0 || pRow < 0 || pCol >= this.cols || pRow >= this.rows) return false;
        return this.data[pRow * this.cols + pCol] > 0;
    }

    /** rectangle de collision monde { x0, y0, x1, y1 } de la tuile (col,row), ou null si vide */
    rectAt(pCol, pRow) {
        if (!this.solidAt(pCol, pRow)) return null;
        const t = this.tileSize;
        const shape = this.shapes[this.data[pRow * this.cols + pCol]];
        const ox = this.originX + pCol * t;
        const oy = this.originY + pRow * t;
        if (!shape) return { x0: ox, y0: oy, x1: ox + t, y1: oy + t };
        return { x0: ox + shape.x0, y0: oy + shape.y0, x1: ox + shape.x1, y1: oy + shape.y1 };
    }

    colAt(pX) { return Math.floor((pX - this.originX) / this.tileSize); }
    rowAt(pY) { return Math.floor((pY - this.originY) / this.tileSize); }

    /**
     * La boite {x,y,hw,hh} (x,y = centre, hw/hh = demi-largeur/hauteur) recouvre-t-elle une tuile pleine ?
     * pDx/pDy decalent la boite avant le test : sert de "capteur" (1 px sous les pieds = suis-je au sol ?).
     */
    overlaps(pBox, pDx = 0, pDy = 0) {
        const x0 = pBox.x + pDx - pBox.hw, x1 = pBox.x + pDx + pBox.hw;
        const y0 = pBox.y + pDy - pBox.hh, y1 = pBox.y + pDy + pBox.hh;
        for (let r = this.rowAt(y0 + EPS); r <= this.rowAt(y1 - EPS); r++) {
            for (let c = this.colAt(x0 + EPS); c <= this.colAt(x1 - EPS); c++) {
                const t = this.rectAt(c, r);
                if (t && x1 - EPS > t.x0 && x0 + EPS < t.x1 && y1 - EPS > t.y0 && y0 + EPS < t.y1) return true;
            }
        }
        return false;
    }
}

/**
 * Deplace pBox de (pDx, pDy) en la bloquant contre les tuiles pleines.
 * Modifie pBox.x / pBox.y et renvoie les contacts { left, right, up, down }.
 */
export function moveAndCollide(pBox, pDx, pDy, pGrid) {
    const hits = { left: false, right: false, up: false, down: false };
    const maxStep = pGrid.tileSize * 0.5;
    const n = Math.max(1, Math.ceil(Math.max(Math.abs(pDx), Math.abs(pDy)) / maxStep));
    const sx = pDx / n;
    const sy = pDy / n;

    for (let i = 0; i < n; i++) {
        if (sx !== 0 && moveAxis(pBox, sx, true, pGrid)) {
            if (sx > 0) hits.right = true; else hits.left = true;
        }
        if (sy !== 0 && moveAxis(pBox, sy, false, pGrid)) {
            if (sy > 0) hits.down = true; else hits.up = true;
        }
    }
    return hits;
}

// deplace sur un axe puis recolle la boite contre le bord de chaque rectangle traverse
function moveAxis(b, d, isX, g) {
    if (isX) b.x += d; else b.y += d;
    const x0 = b.x - b.hw, x1 = b.x + b.hw, y0 = b.y - b.hh, y1 = b.y + b.hh;
    let hit = false;
    for (let r = g.rowAt(y0 + EPS); r <= g.rowAt(y1 - EPS); r++) {
        for (let c = g.colAt(x0 + EPS); c <= g.colAt(x1 - EPS); c++) {
            const t = g.rectAt(c, r);
            if (!t || !(x1 - EPS > t.x0 && x0 + EPS < t.x1 && y1 - EPS > t.y0 && y0 + EPS < t.y1)) continue;
            hit = true;
            if (isX) b.x = d > 0 ? Math.min(b.x, t.x0 - b.hw) : Math.max(b.x, t.x1 + b.hw);
            else b.y = d > 0 ? Math.min(b.y, t.y0 - b.hh) : Math.max(b.y, t.y1 + b.hh);
        }
    }
    return hit;
}
