import { Container, Text } from '../../../core/fff.js';
import { BaseScreen } from '../../../engine/BaseScreen.js';
import { Config } from '../../../engine/Config.js';
import { Datas } from '../../../engine/Datas.js';
import { GameInput } from '../../../engine/GameInput.js';
import { TouchControls } from '../../../engine/TouchControls.js';
import { Collectable } from '../entities/Collectable.js';
import { PlatformPlayer } from '../entities/PlatformPlayer.js';
import { ScreenTitle } from './ScreenTitle.js';

export class ScreenGameOver extends BaseScreen {
    start() {
        this._nextScreen = ScreenTitle;
        super.start();
        this.visible = true;

        this.stage.addChild(Datas.atlas[Datas.BG]);

        let titleTxt = new Text("1500", { fontFamily: Config.DEFAULT_FONT, fill: 0xDD00DD, fontSize: 72, align:"center",letterSpacing:4 });
        titleTxt.position.set( Math.floor( (Config.STAGEWIDTH - titleTxt.width) / 2 ) , Math.floor(Config.STAGEHEIGHT * 1/3) );
        this.stage.addChild(titleTxt);
        
        let container = this.container = new Container();
        container.x = container.y = 16;
        this.stage.addChild(container);

        this.stage.addChild(Datas.atlas[Datas.FG]);

        // appareil tactile : un bouton pour continuer (action1)
        if (TouchControls.isTouchDevice()) {
            this.stage.addChild(TouchControls.create(this.gameInput1, {
                buttons: [{ key: 'action1', x: Config.STAGEWIDTH - 100, y: 400, radius: 56, label: 'OK' }]
            }));
        }

        this.player = new PlatformPlayer(
            this.gameInput1,
            32-16, 0-16,
            this);    

        this.collectables = [
            new Collectable(9, 13),
            new Collectable(9, 12),
            new Collectable(9, 11),
            new Collectable(10, 10),
            new Collectable(11, 10),
            new Collectable(12, 10),
            new Collectable(13, 11),
            new Collectable(13, 12),
            new Collectable(13, 13),
            new Collectable(12, 13),
            new Collectable(11, 13),
            new Collectable(11, 12),

            new Collectable(9, 19),
            new Collectable(9, 18),
            new Collectable(9, 17),
            new Collectable(10, 16),
            new Collectable(11, 16),
            new Collectable(12, 16),
            new Collectable(13, 17),
            new Collectable(13, 18),
            new Collectable(13, 19),
            new Collectable(12, 19),
            new Collectable(11, 19),
            new Collectable(11, 18)            
        ];    
        
        // collectables
        for (let i = 0; i < this.collectables.length; i++) {
            let currentCollectable = this.collectables[i];
            currentCollectable.x = currentCollectable.bb.x;
            currentCollectable.y = currentCollectable.bb.y;
            this.container.addChild(currentCollectable);
        }  

        this.framecount = 0;
        this.collectCount = 0;
    }
    
    end() {
        super.end();
    }

    onEnterFrame(pSeconds) {
        const pDt = pSeconds * Datas.DT_SCALE;
        this.time = (this.time || 0) + pDt;
        // maj des input
        this.gameInput1.update(pSeconds);
        //
        this.framecount++;
        if(this.framecount % 10 == 0){
            for (let i = 0; i < this.collectables.length; i++) {
                this.collectables[i].deactivate();
            }

            this.collectables[this.collectCount % this.collectables.length].activate();
            this.collectCount++;
        }
    };

    playerAction(pValue){
        if(pValue == GameInput.ACTION1){
            this.transitionOut({ freeze: true });
        }else if(pValue == GameInput.ACTION2){
            // --
        }else if(pValue == GameInput.ACTION3){
            // --
        }
    }
}